// One workspace-wide personal token. ClickUp personal tokens are prefixed `pk_`
// and do not expire.
//
// The header is `Authorization: pk_...` with NO `Bearer` prefix. Adding one
// returns OAUTH_019 rather than a clear 401, which reads like a scope problem
// and sends you looking in the wrong place for an afternoon.
const token = Buffer.from($json.payload.data, 'base64').toString('utf8').trim();
return [{ json: { clickup_token: token } }];

// Field definitions. Landed for two reasons: dropdowns arrive as an orderindex
// integer and need their options to become labels, and comparing what ClickUp
// actually has against ref.clickup_field_map is the drift check that catches a
// relationship field pointing at the wrong client's list.
const ctx = $('Loop over lists').first().json;
const INGESTED_AT = new Date().toISOString();
const today = INGESTED_AT.slice(0, 10);

const fields = ($input.first().json.fields) || [];
return fields.map(f => {
  const cfg = f.type_config || {};
  return { json: {
    client_id: ctx.client_id,
    ingested_at: INGESTED_AT,
    snapshot_date: today,
    list_kind: ctx.list_kind,
    list_id: String(ctx.list_id),
    field_id: f.id,
    name: f.name,
    type: f.type,
    // Present only on list_relationship fields. This is the column that shows
    // Venev's `Concept` field aiming at Manami's list.
    target_list_id: cfg.subcategory_id ? String(cfg.subcategory_id) : null,
    options_json: JSON.stringify(cfg.options || []),
    payload_json: JSON.stringify(f)
  }};
});

// Tasks, with every custom field resolved to something a human can read six
// months from now.
//
// ── Dropdowns ──────────────────────────────────────────────────────────────
// ClickUp returns the option's ORDERINDEX, an integer. Storing 2 is storing
// nothing: reorder the options and the meaning of every historical row changes
// underneath you. Resolved here against the definitions fetched a moment ago.
//
// ── The `Creative ID` placeholder ──────────────────────────────────────────
// That field holds the literal string "Creative ID" on all 65 Manami tasks. It
// is a field name that leaked into the data. It is nulled here AND in
// stg_clickup_tasks — twice on purpose, because a value that looks like an ad
// id but is not would create a phantom ad joining to nothing, and it would
// appear in every breakdown as an untagged row that no one could find.
const ctx = $('Loop over lists').first().json;
const INGESTED_AT = new Date().toISOString();
const today = INGESTED_AT.slice(0, 10);

// `.first()`, never `.item`: paired-item resolution across a chain this wide
// pegs a CPU core with no network activity at all.
const defs = new Map();
for (const it of $('Transform field defs').all()) {
  const j = it.json;
  defs.set(j.field_id, { name: j.name, type: j.type, options: JSON.parse(j.options_json || '[]') });
}

const label = (def, value) => {
  if (value === null || value === undefined || value === '') return null;
  const opts = def?.options || [];
  const byIndex = opts.find(o => String(o.orderindex) === String(value));
  const byId = opts.find(o => String(o.id) === String(value));
  return (byIndex || byId)?.name ?? null;
};

const tasks = [];
for (const it of $input.all()) {
  const j = it.json;
  if (Array.isArray(j.tasks)) tasks.push(...j.tasks);
  else if (j.id) tasks.push(j);
}

const ts = v => (v ? new Date(Number(v)).toISOString() : null);

return tasks.map(t => {
  const custom = (t.custom_fields || []).map(f => {
    const def = defs.get(f.id) || { name: f.name, type: f.type, options: (f.type_config || {}).options || [] };
    const v = f.value;
    let value_text = null, value_num = null, value_ids = [];

    if (f.type === 'drop_down') {
      value_text = label(def, v);
    } else if (f.type === 'list_relationship' || f.type === 'tasks') {
      value_ids = Array.isArray(v) ? v.map(x => String(x.id ?? x)) : [];
      value_text = Array.isArray(v) ? v.map(x => x.name).filter(Boolean).join(', ') || null : null;
    } else if (f.type === 'number' || f.type === 'currency') {
      value_num = (v === null || v === undefined || v === '') ? null : Number(v);
    } else if (f.type === 'date') {
      value_text = v ? new Date(Number(v)).toISOString().slice(0, 10) : null;
    } else if (f.type === 'labels') {
      const opts = def.options || [];
      value_text = Array.isArray(v)
        ? v.map(id => opts.find(o => o.id === id)?.label ?? null).filter(Boolean).join(', ') || null
        : null;
    } else {
      value_text = (v === null || v === undefined || v === '') ? null : String(v);
    }

    // A value identical to its own field's name is a placeholder somebody typed
    // over, not data.
    if (value_text !== null && value_text.trim() === (f.name || '').trim()) value_text = null;

    return { field_id: f.id, name: f.name, type: f.type, value_text, value_num, value_ids };
  });

  return { json: {
    client_id: ctx.client_id,
    ingested_at: INGESTED_AT,
    snapshot_date: today,
    list_kind: ctx.list_kind,
    list_id: String(ctx.list_id),
    task_id: String(t.id),
    task_name: t.name ?? '',
    task_url: t.url ?? null,
    status: t.status?.status ?? null,
    status_type: t.status?.type ?? null,
    date_created: ts(t.date_created),
    date_updated: ts(t.date_updated),
    date_closed: ts(t.date_closed),
    assignees: (t.assignees || []).map(a => a.username || a.email).filter(Boolean),
    custom_fields: custom,
    payload_json: JSON.stringify(t)
  }};
});
